// SwiftUI
struct TermsRow: View {
    @State private var state: JdCheckboxState = .off

    var body: some View {
        JdCheckbox("약관에 동의합니다", state: $state)
        // 부분 선택(mixed)을 순환에 넣으려면:
        JdCheckbox("전체 선택", state: $state, indeterminateAllowed: true)
    }
}

